-- init: the schema from prisma/schema.prisma, plus the SQL that Prisma cannot express.
-- Generated by `prisma migrate dev --create-only`, then edited by hand (DB-03; ADR 0008 section 8;
-- FU-DB-01, FU-DB-02, FU-DB-09). Nothing else differs from what Prisma generated:
--   - Extensions pgcrypto and citext, first, before the first CITEXT column.
--   - Five identity columns: BIGSERIAL becomes BIGINT GENERATED ALWAYS AS IDENTITY.
--   - Five list columns become NOT NULL (Prisma emits scalar lists as nullable).
--   - At the end: 12 named CHECK constraints, 2 partial indexes, and the users.updated_at trigger.
-- No password and no role in this file. The app_user role is the next migration.

-- Extensions
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS citext;

-- CreateEnum
CREATE TYPE "user_role" AS ENUM ('SUPER_ADMIN', 'RECRUITER', 'AUTHOR', 'REVIEWER');

-- CreateEnum
CREATE TYPE "difficulty" AS ENUM ('EASY', 'MEDIUM', 'HARD');

-- CreateEnum
CREATE TYPE "question_type" AS ENUM ('CODING', 'MCQ', 'SHORT_ANSWER');

-- CreateEnum
CREATE TYPE "proctor_profile" AS ENUM ('STANDARD', 'STRICT');

-- CreateEnum
CREATE TYPE "session_status" AS ENUM ('INVITED', 'OPENED', 'CONSENTED', 'VERIFIED', 'IN_PROGRESS', 'PAUSED', 'SUBMITTED', 'GRADED', 'UNDER_REVIEW', 'COMPLETED', 'EXPIRED', 'APPEALED', 'DECLINED');

-- CreateEnum
CREATE TYPE "submission_kind" AS ENUM ('RUN', 'SUBMIT');

-- CreateEnum
CREATE TYPE "media_stream" AS ENUM ('SCREEN', 'WEBCAM', 'AUDIO', 'SIDE_CAMERA', 'ROOM_SCAN');

-- CreateEnum
CREATE TYPE "severity" AS ENUM ('LOW', 'MEDIUM', 'HIGH');

-- CreateEnum
CREATE TYPE "risk_band" AS ENUM ('LOW', 'MEDIUM', 'HIGH');

