-- DB-03: CHECK constraints (ADR 0008 section 5). Explicit names, so tests can assert them (FU-DB-09).
-- The names are the ones Postgres would give an unnamed inline CHECK.
ALTER TABLE "organizations" ADD CONSTRAINT "organizations_retention_days_check" CHECK ("retention_days" BETWEEN 7 AND 730);

ALTER TABLE "users" ADD CONSTRAINT "users_check" CHECK ("password_hash" IS NOT NULL OR "set_password_token_hash" IS NOT NULL);

ALTER TABLE "tests" ADD CONSTRAINT "tests_duration_minutes_check" CHECK ("duration_minutes" BETWEEN 5 AND 480);

ALTER TABLE "test_questions" ADD CONSTRAINT "test_questions_check" CHECK ("question_version_id" IS NOT NULL OR "random_rule" IS NOT NULL);

ALTER TABLE "invitations" ADD CONSTRAINT "invitations_check" CHECK ("window_end" > "window_start");

ALTER TABLE "sessions" ADD CONSTRAINT "sessions_risk_score_check" CHECK ("risk_score" BETWEEN 0 AND 100);

ALTER TABLE "session_questions" ADD CONSTRAINT "session_questions_check" CHECK (("scoring" = 'MANUAL') = ("scored_by" IS NOT NULL AND "scored_at" IS NOT NULL));

ALTER TABLE "consents" ADD CONSTRAINT "consents_check" CHECK (("signed_at" IS NULL) <> ("declined_at" IS NULL));

ALTER TABLE "consents" ADD CONSTRAINT "consents_check1" CHECK ("signed_at" IS NULL OR "signed_name" IS NOT NULL);

ALTER TABLE "identity_checks" ADD CONSTRAINT "identity_checks_attempt_check" CHECK ("attempt" BETWEEN 1 AND 2);

ALTER TABLE "identity_checks" ADD CONSTRAINT "identity_checks_check" CHECK (("status" = 'REVIEWED') = ("manual_decision" IS NOT NULL AND "reviewed_by" IS NOT NULL AND "reviewed_at" IS NOT NULL));

ALTER TABLE "appeals" ADD CONSTRAINT "appeals_check" CHECK (("status" = 'OVERTURNED') = ("new_verdict" IS NOT NULL));

-- DB-03: partial indexes (the other 22 indexes are above). NFR-05: the retention job reads the second one.
CREATE INDEX "sessions_risk_band_idx" ON "sessions"("risk_band") WHERE "status" IN ('GRADED', 'UNDER_REVIEW');

CREATE INDEX "sessions_retention_anchor_at_idx" ON "sessions"("retention_anchor_at") WHERE "retention_anchor_at" IS NOT NULL;

-- DB-03: users.updated_at is kept by the database, not by Prisma (the schema has no @updatedAt).
CREATE FUNCTION "set_updated_at"() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  NEW."updated_at" = now();
  RETURN NEW;
END;
$$;

CREATE TRIGGER "users_set_updated_at"
BEFORE UPDATE ON "users"
FOR EACH ROW
EXECUTE FUNCTION "set_updated_at"();
